<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Password Entropy Calculator','description'=>'Estimate password entropy in bits from length and character set.','url'=>'https://smarttoolz.in/tools/password-entropy-calculator/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">PASSWORD ENTROPY</span><h1>Password Entropy Calculator</h1><p>Estimate theoretical entropy from a password's character set and length.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Password<input id="p" type="password"></label><button id="go" class="tool-btn">Calculate Entropy</button><p id="out" style="font-size:20px;font-weight:800"></p></div></section></main><script>(()=>{const p=document.getElementById('p'),o=document.getElementById('out');document.getElementById('go').onclick=()=>{let s=p.value;if(!s){o.textContent='Enter a password.';return}let set=(/[a-z]/.test(s)?26:0)+(/[A-Z]/.test(s)?26:0)+(/\d/.test(s)?10:0)+(/[^A-Za-z0-9]/.test(s)?33:0);o.textContent=`Estimated entropy: ${(s.length*Math.log2(set)).toFixed(1)} bits · Character set: ${set}`}})();</script><?php smarttoolz_tool_page_end(); ?>